/* From Uiverse.io by yaroslavas2001 - Tags: notification */
.__UIV_SCOPE__ .notification {
  height: 12em;
  width: 19em;
}

.__UIV_SCOPE__ .mirrow {
  height: 12em;
  width: 19em;
  position: relative;
  background: linear-gradient(45deg, #6720D9, #0062FF, #0085FF, #009CFF, #00AED3, #00BD9B);
  background-size: 400% 400%;
  animation: gradient 15s ease infinite;
}

.__UIV_SCOPE__ .fragment {
  position: absolute;
  filter: blur(5px);
  fill: rgba(252, 252, 252, 0.7);
  transition: all 2s ease-in-out;
}

.__UIV_SCOPE__ .mirrow:hover .fragment {
  height: 0em;
  width: 0em;
  filter: blur(10px);
}

.__UIV_SCOPE__ .fragment1 {
  width: 9.5em;
  height: 7.5em;
}

.__UIV_SCOPE__ .mirrow:hover .fragment1 {
  transform: translate(-15px, -15px);
}

.__UIV_SCOPE__ .fragment2 {
  width: 8em;
  height: 6.5em;
  bottom: 0px;
  left: 0px;
}

.__UIV_SCOPE__ .mirrow:hover .fragment2 {
  transform: translate(-15px, 15px);
}

.__UIV_SCOPE__ .fragment3 {
  width: 7em;
  height: 7em;
  top: 0px;
  right: 25%;
  left: 40%;
}

.__UIV_SCOPE__ .mirrow:hover .fragment3 {
  transform: translate(0px, -15px);
}

.__UIV_SCOPE__ .fragment4 {
  width: 8em;
  height: 7em;
  top: 0px;
  right: 0px
}

.__UIV_SCOPE__ .mirrow:hover .fragment4 {
  transform: translate(15px, -15px);
}

.__UIV_SCOPE__ .fragment5 {
  width: 12em;
  height: 6em;
  bottom: 0px;
  right: 0px;
}

.__UIV_SCOPE__ .mirrow:hover .fragment5 {
  transform: translate(15px, 15px);
}

.__UIV_SCOPE__ .level {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  height: 100%;
}

.__UIV_SCOPE__ .btn_block {
  display: flex;
}

.__UIV_SCOPE__ .level_text {
  font-weight: bold;
  font-size: 22px;
  color: #fff;
  margin: 0px 0px 5px 0px;
}

.__UIV_SCOPE__ .level_sub_text {
  font-size: 13px;
  color: #fff;
  margin: 0px 0px 10px 0px;
}

.__UIV_SCOPE__ .btn {
  background: transparent;
  border: 1px solid #fff;
  border-radius: 14px;
  cursor: pointer;
  margin: 0px 2px;
  color: #fff;
  font-size: 12px;
  transition: all 1s ease-in-out;
  padding: 2px 6px;
}

.__UIV_SCOPE__ .btn:hover {
  background: #fff;
  color: #000;
}

@keyframes gradient {
  0% {
    background-position: 0% 50%;
  }

  50% {
    background-position: 100% 50%;
  }

  100% {
    background-position: 0% 50%;
  }
}

.__UIV_SCOPE__ .star {
  position: absolute;
  height: 28px;
  width: 28px;
  fill: yellow;
}

.__UIV_SCOPE__ .star1 {
  animation: Orbita1 15s linear infinite;
}

@keyframes Orbita1 {
  from {
    transform: rotate(0deg) translateX(80px) rotate(0deg);
  }

  to {
    transform: rotate(360deg) translateX(80px) rotate(-360deg);
  }
}

